class Spacecraft {
  constructor(initialEnergy, maxEnergy) {
    // TODO: Make energyLevel a private field
    this.energyLevel = initialEnergy;
    this.maxEnergy = maxEnergy;
    if (this.energyLevel < 0 || this.energyLevel > this.maxEnergy) {
      throw new Error("Initial energy must be between 0 and max energy.");
    }
  }

  chargeEnergy(amount) {
    // TODO: Update the private energyLevel
    if (amount < 0) return false;
    this.energyLevel = Math.min(this.energyLevel + amount, this.maxEnergy);
    return true;
  }

  consumeEnergy(amount) {
    // TODO: Update the private energyLevel and prevent it from going below 0
    if (amount < 0) return false;
    this.energyLevel -= amount; // This can go below 0
    return true;
  }

  getEnergyLevel() {
    // TODO: Return the private energyLevel
    return this.energyLevel;
  }
}

// Example usage that should be prevented or controlled
const ship = new Spacecraft(100, 200);
// ship.energyLevel = -50; // This direct modification should be impossible!
console.log(`Initial energy: ${ship.getEnergyLevel()}`);

