class Spacecraft {
  #energyLevel;
  #maxEnergy;

  constructor(initialEnergy, maxEnergy) {
    this.#maxEnergy = maxEnergy;
    if (initialEnergy < 0 || initialEnergy > this.#maxEnergy) {
      throw new Error("Initial energy must be between 0 and max energy.");
    }
    this.#energyLevel = initialEnergy;
  }

  chargeEnergy(amount) {
    if (amount < 0) return false;
    this.#energyLevel = Math.min(this.#energyLevel + amount, this.#maxEnergy);
    return true;
  }

  consumeEnergy(amount) {
    if (amount < 0) return false;
    if (this.#energyLevel - amount < 0) {
      this.#energyLevel = 0; // Prevent negative energy
      return false; // Indicate not enough energy was available
    }
    this.#energyLevel -= amount;
    return true;
  }

  getEnergyLevel() {
    return this.#energyLevel;
  }
}

const ship = new Spacecraft(100, 200);
// Attempting to directly modify ship.#energyLevel would cause a syntax error, demonstrating encapsulation.
ship.chargeEnergy(50);
console.log(`Energy after charging: ${ship.getEnergyLevel()}`); // Expected: 150
ship.consumeEnergy(100);
console.log(`Energy after consuming: ${ship.getEnergyLevel()}`); // Expected: 50
ship.consumeEnergy(70); // Should set energy to 0 and return false
console.log(`Energy after over-consuming: ${ship.getEnergyLevel()}`); // Expected: 0

